        String codes = entity.getCreditReasonCodes();
        List<String> reasonCodes = codes == null || codes.isEmpty()
                ? List.of() : Arrays.asList(codes.split(REASON_CODE_SEPARATOR));
        return new CreditCheck(entity.getCreditApproved(), entity.getCreditScore(), reasonCodes,
                entity.getCreditCheckedAt(), entity.getCreditProviderName(), entity.getCreditProviderVersion());
    }
}
