import org.springframework.stereotype.Component;

/** 업체 SDK 를 출력 포트에 맞춘다. 실제 서버로 바꿀 때는 CreditCheckClient 빈만 교체하면 된다. */
@Component
public class CreditCheckAdapter implements CheckCreditPort {

    private final CreditCheckClient client;

    public CreditCheckAdapter(CreditCheckClient client) {
        this.client = client;
    }

    @Override
    public CreditCheck checkCredit(Member member) {
        CreditCheckResponse r = client.check(member.getId().toString(), member.getName());
        CreditCheckResponse.Provider p = r.provider;
        return new CreditCheck(r.approved, r.score, r.reasonCodes, r.checkedAt,
                p != null ? p.name : null, p != null ? p.version : null);
    }
}
